export function applyLinuxProjectReading(module: RawCourse["modules"][number]) {
	const decorate = (
		item: RawCourse["modules"][number]["curriculum"][number]
	) => {
		const url = item.projectLink
			? linuxPinnedCourseUrl(item.projectLink)
			: undefined;
		const selected = url ? linuxCourseResource(url) : null;
		if (!selected) return item;
		const notebook = item.title.startsWith("Troubleshooting Notebook:");
		const continuation =
			"continuationItemId" in selected.definition &&
			item.title.endsWith(": Extension Challenge");
		const projectTitle = projectTitles[selected.pack];
		const projectGuide = linuxProjectGuides[selected.pack]!.replace(
			/\bTODO\b/g,
			"`TODO`"
		)
			.replace("Instructor walkthrough", "Walkthrough")
			.replaceAll("an instructor walkthrough", "a guided walkthrough")
			.replaceAll(
				"## Policy model and the named repair",
				"## Policy model and implementation"
			);
		return {
			...item,
			...(!notebook && !continuation && projectTitle
				? { id: selected.definition.coreItemId, title: projectTitle }
				: {}),
			projectLink: url,
			solutionLink: item.solutionLink
				? linuxPinnedCourseUrl(item.solutionLink)
				: undefined,
			ideImport: true,
			preserveInstructions: true,
			content: notebook
				? `${item.content}\n\n**Continue the existing lab:** Opening this notebook's starter or reference in the IDE reopens the matching core project. Keep the notebook's own progress record; edit the same source attempt rather than creating a second program. The imported README contains the complete operating guide.\n\n**Independent investigation:** Record the Linux host and active identity, the exact command and input, a prediction, stdout, stderr, exit status, the first differing observation, a focused correction, a changed case and the verified undo. Include the module's worksheet or provisioning, serving, restoration and scheduler observations where relevant. A supplied reference run does not complete this record.`
				: continuation
					? [
							selected.pack === "LS-04-linux-systems-lab-17"
								? "**Continue the existing operations attempt:** This optional challenge reopens the matching required capstone project for the selected role and keeps its own lesson progress. Preserve the first runbook and trusted backup. Repeat the documented changed-fictional-data slice: compare cached service data before restart, a new service invocation after restart, a fresh timer-triggered backup and a second restore into a new path. Retain the original restore and explain each changed observation. The separate transfer and extension practice projects below have their own source attempts."
								: "**Continue the existing deployment attempt:** This optional challenge reopens the matching core project for the selected role. Keep its separate lesson progress record while editing the same saved files. Retain the first evidence before running the reversed release order and one rejected candidate; explain why a response with status 200 can still require rollback. The integrity and concurrent-publisher projects below investigate separate questions.",
							projectGuide
						].join("\n\n")
					: [
							"**Project workflow:** Open one selected role after confirming the IDE import. Save and download the ZIP, preserve every role path and fixture, then execute the commands in an owned Linux lab. Earlier work remains available as a separate project.",
							projectGuide,
							networkCommandCheckpoints[selected.pack]
						]
							.filter(Boolean)
							.join("\n\n")
		};
	};
	return {
		...module,
		curriculum: module.curriculum.map(decorate),
		supplementalProjects: module.supplementalProjects.map(decorate)
	};
}
